                        bjzm戈逼: {
                            enable: 'phaseUse',
                            usable: 1,
                            filterTarget(card, player, target) {
                                return target !== player;
                            },
                            aiJudge(card, player, target, bool, choices) {
                                var left3 = false,
                                    right3 = false;
                                var eff_left = 0,
                                    eff_right = 0;
                                let left = [],
                                    right = [];
                                let left2 = player.previous,
                                    right2 = player.next;
                                while (left2 && ![target, player].includes(left2) && right2 && ![target, player].includes(right2)) {
                                    left.push(left2);
                                    right.push(right2);
                                    left2 = left2.previous;
                                    right2 = right2.next;
                                }
                                if (target == left2) {
                                    for (var i of left) {
                                        if (lib.filter.targetEnabled2(card, player, i)) {
                                            left3 = true;
                                            eff_left += get.effect(i, card, player, player);
                                        }
                                    }
                                }
                                if (target == right2) {
                                    for (var i of right) {
                                        if (lib.filter.targetEnabled2(card, player, i)) {
                                            right3 = true;
                                            eff_right += get.effect(i, card, player, player);
                                        }
                                    }
                                }
                                if (left3 && right3) {
                                    if (!bool) return Math.max(eff_left, eff_right);
                                    if (eff_left > Math.max(0, eff_right)) return '↖顺时针';
                                    if (eff_right > Math.max(0, eff_left)) return '逆时针↗';
                                    //return 'cancel2';
                                } else if (left3) {
                                    if (bool) return eff_left > 0 ? '↖顺时针' : choices.randomGet();
                                    return eff_left;
                                } else if (right3) {
                                    if (bool) return eff_right > 0 ? '↖顺时针' : choices.randomGet();
                                    return eff_right;
                                }
                                //else return bool?'cancel2':0;
                                if (choices) return choices.randomGet();
                            },
                            content() {
                                'step 0';
                                var choices = [];
                                let left = [],
                                    right = [];
                                let left2 = player.previous,
                                    right2 = player.next;
                                while (left2 && ![target, player].includes(left2) && right2 && ![target, player].includes(right2)) {
                                    left.push(left2);
                                    right.push(right2);
                                    left2 = left2.previous;
                                    right2 = right2.next;
                                }
                                if (target == left2) {
                                    choices.push('↖顺时针');
                                }
                                if (target == right2) {
                                    choices.push('逆时针↗');
                                }
                                player
                                    .chooseControl(choices, true)
                                    .set('prompt', get.prompt('bjzm戈逼'))
                                    .set('prompt2', '令自己和' + get.translation(target) + '某个方向之间的所有角色依次使用【决斗】')
                                    .set('choices', choices)
                                    .set('ai', function (event, player) {
                                        return lib.skill.bjzm戈逼.aiJudge(game.createCard({ name: 'juedou' }), event.player, target, true, choices);
                                    });
                                ('step 1');
                                if (result.control != 'cancel2') {
                                    var targets = [];
                                    if (result.control == '↖顺时针') {
                                        var current = player.previous;
                                        while (current != target) {
                                            targets.push(current);
                                            current = current.previous;
                                        }
                                    } else {
                                        var current = player.next;
                                        while (current != target) {
                                            targets.push(current);
                                            current = current.next;
                                        }
                                    }
                                    player.chooseTarget([1, targets.length], function (card, player, target) {
                                        return targets.includes(target);
                                    });
                                    if (!event.isMine() && !event.isOnline()) game.delayx();
                                } else event.finish();
                                ('step 2');
                                if (result.targets?.length) {
                                    event.targets11 = result.targets;
                                    event.targets11.push(target);
                                } else {
                                    event.targets11 = [target];
                                }
                                ('step 3');
                                event.target1 = event.targets11.shift();
                                player.useCard({ name: 'juedou' }, event.target1);
                                ('step 4');
                                if (event.targets11.length) event.goto(3);
                                ('step 5');
                                player.draw(
                                    2 *
                                    player.getHistory('sourceDamage', function (evt) {
                                        var card = evt.card;
                                        if (!card || card.name != 'juedou') return false;
                                        var evtx = evt.getParent('useCard');
                                        return evtx.card == card && evtx.parent == event;
                                    }).length,
                                );
                                ('step 6');
                                game.log('【戈迫】摸牌');
                            },
                            ai: {
                                order: 7,
                                result: {
                                    target: -1,
                                },
                                effect: {
                                    player_use(card, player, target) {
                                        if (!target || player._bjzm戈逼_judging || ui.selected.targets.length || player == target || target.hasSkill('nodis')) return;
                                        if (typeof card != 'object' || (card.name != 'juedou' && get.type(card) != 'trick')) return false;
                                        player._bjzm戈逼_judging = true;
                                        var effect = lib.skill.bjzm戈逼.aiJudge(card, player, target);
                                        delete player._bjzm戈逼_judging;
                                        if (effect > 0) return [1, effect / Math.max(0.01, get.attitude(player, player))];
                                    },
                                },
                            },
                            group: 'bjzm戈逼防止受到伤害',
                        },
