                        bjzm说纵: {
                            enable: 'phaseUse',
                            filter(event, player) {
                                return (player.getStat('skill').bjzm说纵 || 0) <= game.countGroup();
                            },
                            filterTarget(card, player, target) {
                                return !target.isLinked() && player.canCompare(target);
                            },
                            content() {
                                'step 0';
                                player.chooseToCompare(target);
                                ('step 1');
                            },
                            ai: {
                                order: 1,
                                result: {
                                    target(player, target) {
                                        var att = get.attitude(player, target);
                                        var oc = target.countCards('h') == 1;
                                        if (att > 0 && oc) return 0;
                                        if (att > 0) return 0;
                                        var players = game.filterPlayer();
                                        for (var i = 0; i < players.length; i++) {
                                            if (players[i] != target && players[i] != player && target.inRange(players[i])) {
                                                if (get.damageEffect(players[i], target, player) > 0) {
                                                    return att > 0 ? att / 2 : att - (oc ? 5 : 0);
                                                }
                                            }
                                        }
                                        return 0;
                                    },
                                    player(player, target) {
                                        if (target.hasSkillTag('jueqing', false, target)) return -10;
                                        var mn = 1;
                                        var hs = player.getCards('h');
                                        for (var i = 0; i < hs.length; i++) {
                                            mn = Math.max(mn, hs[i].number);
                                        }
                                        var max = player.maxHp - hs.length;
                                        var players = game.filterPlayer();
                                        for (var i = 0; i < players.length; i++) {
                                            if (get.attitude(player, players[i]) > 0) {
                                                return 0;
                                            }
                                        }
                                        switch (max) {
                                            case 0:
                                                return mn == 13 ? 0 : 20;
                                            case 1:
                                                return mn >= 12 ? 0 : 15;
                                            case 2:
                                                return 0;
                                            case 3:
                                                return 1;
                                            default:
                                                return max;
                                        }
                                    },
                                },
                                expose: 0.2,
                            },
                        },
