                        bjzm纵局: {
                            init(player, skill) {
                                player.storage.bjzm纵局X = 0;
                                lib.skill.标记初始化.initializeStorage('bjzm纵局X', 0, player, 'phase');
                                player.markSkill('bjzm纵局');
                            },
                            intro: {
                                mark(dialog, content, player) {
                                    if (player.isUnderControl(true)) {
                                        var list = [];
                                        var max = player.storage.bjzm纵局X;
                                        if (max == 0) return false;
                                        var num = Math.min(max, ui.cardPile.childElementCount);
                                        for (var i = 0; i < num; i++) {
                                            list.push(ui.cardPile.childNodes[i]);
                                        }
                                        dialog.addSmall(list);
                                    } else {
                                        dialog.addText('牌堆顶的' + num + '张牌');
                                    }
                                },
                                content(content, player) {
                                    if (player.isUnderControl(true)) {
                                        var list = [];
                                        var max = player.storage.bjzm纵局X;
                                        if (max == 0) return false;
                                        var num = Math.min(max, ui.cardPile.childElementCount);
                                        for (var i = 0; i < num; i++) {
                                            list.push(ui.cardPile.childNodes[i]);
                                        }
                                        return get.translation(list);
                                    } else {
                                        return '牌堆顶的' + num + '张牌';
                                    }
                                },
                            },
                            trigger: { global: ['loseAfter', 'cardsDiscardAfter'] },
                            forced: true,
                            filter(event, player) {
                                if (event.name == 'lose' && event.position != ui.discardPile) return false;
                                return _status.currentPhase;
                            },
                            content() {
                                'step 0';
                                var list1 = [];
                                var list2 = [];
                                for (var i = 0; i < trigger.cards.length; i++) {
                                    var st = get.color(trigger.cards[i]);
                                    if (st == 'red') {
                                        list1.push(trigger.cards[i]);
                                    } else if (st == 'black') {
                                        list2.push(trigger.cards[i]);
                                    }
                                }
                                game.getGlobalHistory(
                                    'cardMove',
                                    function (evt) {
                                        if (evt == trigger || (evt.name != 'lose' && evt.name != 'cardsDiscard')) return false;
                                        if (evt.name == 'lose' && evt.position != ui.discardPile) return false;
                                        for (var i = 0; i < evt.cards.length; i++) {
                                            var card = evt.cards[i];
                                            list1.remove(card);
                                            list2.remove(card);
                                        }
                                    },
                                    trigger,
                                );
                                event.list1 = list1.concat(list2);
                                if (list1.length != 0 || list2.length != 0) {
                                    player.storage.bjzm纵局X += list1.length;
                                    player.storage.bjzm纵局X += list2.length;
                                } else event.finish();
                                ('step 1');
                                var customHistory = player.getHistory('custom', function (evt) {
                                    return evt.bjzm纵局;
                                });
                                var flag = false;
                                for (let card of event.list1) {
                                    if (card.name == 'sha') {
                                        flag = true;
                                    }
                                }
                                if (flag) player.getHistory('custom').push({ bjzm纵局: true });
                                if (flag && player.storage.bjzm纵局X > 1 && !customHistory.length) {
                                    var cards = get.cards(player.storage.bjzm纵局X);
                                    game.cardsGotoOrdering(cards);
                                    var next = player.chooseToMove();
                                    next.set('list', [['调整牌堆顶的牌', cards]]);
                                    next.set('prompt', '纵局:你以任意顺序调换这些牌');
                                    next.processAI = function (list) {
                                        var cards = list[0][1],
                                            player = _status.event.player;
                                        const target = _status.currentPhase?.next || player;
                                        const att = get.attitude(player, target);
                                        const top = [],
                                            bottom = cards;
                                        for (const i of target.getCards('j')) {
                                            const judge = get.judge(i);
                                            bottom.sort((a, b) => (judge(b) - judge(a)) * att); //态度大于0价值高的牌放前面
                                            if (bottom.length) {
                                                top.push(bottom.shift());
                                            }
                                        }
                                        bottom.sort((a, b) => (get.value(b) - get.value(a)) * att); //态度大于0价值高的牌放前面
                                        while (bottom.length) {
                                            top.push(bottom.shift());
                                        }
                                        var cardsList = top.concat(bottom);
                                        if (_status.currentPhase == player) {
                                            var value;
                                            cardsList.sort(function (a, b) {
                                                if (get.type(a) == 'basic') {
                                                    value = -100;
                                                } else {
                                                    value = 100;
                                                }
                                                return get.value(b, player) - Math.max(get.value(a, player), value);
                                            });
                                            return [cardsList];
                                        }
                                        if (get.attitude(player, _status.currentPhase.next) > 0) {
                                            return [top.concat(bottom)];
                                        } else {
                                            return [bottom.concat(top)];
                                        }
                                    };
                                } else {
                                    event.finish();
                                    return;
                                }
                                ('step 2');
                                var top = result.moved[0];
                                top.reverse();
                                for (var i = 0; i < top.length; i++) {
                                    ui.cardPile.insertBefore(top[i], ui.cardPile.firstChild);
                                }
                                game.updateRoundNumber();
                            },
                        },
