                        bjzm齐真: {
                            trigger: { global: ['phaseJudgeAfter', 'phaseDrawAfter', 'phaseUseAfter', 'phaseDiscardAfter'] },
                            filter(event, player) {
                                //return event.player.hasMark('bjzm玄同游戏开始时');
                                return event.player.hasMark('bjzm玄同游戏开始时') && !player.storage.bjzm玄同types.includes(event.name);
                            },
                            check(event, player) {
                                if (get.attitude(player, event.player) > 0) {
                                    return event.name == 'phaseDraw' || event.name == 'phaseUse';
                                } else {
                                    return event.name == 'phaseDiscard';
                                }
                            },
                            content() {
                                'step 0';
                                player.chooseTarget('你令一名角色执行一个额外的主要阶段', true).set('ai', function (target) {
                                    if (get.attitude(player, target) > 0) {
                                        if (!target.countCards('h')) return 4;
                                        return target.hp / target.countCards('h');
                                    }
                                    return 0;
                                });
                                ('step 1');
                                if (result.targets?.length) {
                                    event.target = result.targets[0];
                                    trigger.player.removeMark('bjzm玄同游戏开始时');
                                    var list = ['判定阶段', '摸牌阶段', '出牌阶段', '弃牌阶段'];
                                    for (var string of list) {
                                        for (var bjzm玄同type of player.storage.bjzm玄同types) {
                                            if (string == bjzm玄同type) list.remove(string);
                                        }
                                    }
                                    player
                                        .chooseControl(list, true, function (event, player) {
                                            if (get.attitude(player, event.target) > 0) {
                                                return ['摸牌阶段', '出牌阶段'].randomGet();
                                            } else {
                                                return '弃牌阶段';
                                            }
                                        })
                                        .set('prompt', get.prompt2('bjzm齐真'));
                                }
                                ('step 2');
                                var control;
                                if (result.control == '摸牌阶段') {
                                    control = 'phaseDraw';
                                } else if (result.control == '出牌阶段') {
                                    control = 'phaseUse';
                                } else if (result.control == '弃牌阶段') {
                                    control = 'phaseDiscard';
                                } else if (result.control == '判定阶段') {
                                    control = 'phaseJudge';
                                }
                                player.storage.bjzm玄同types.push(result.control);
                                eval('event.target.' + control + '()');
                                ('step 3');
                                player.useSkill('bjzm玄同');
                            },
                        },
