                        bjzm伐城: {
                            trigger: { global: ['damageBegin3', 'loseHpBefore', 'recoverBefore'] },
                            usable: 1,
                            filter(event, player) {
                                return player.getStorage('bjzm征从') && player.getStorage('bjzm征从').length;
                            },
                            check(event, player) {
                                if (get.attitude(player, event.player) > 0 && event.name == 'recover') {
                                    if (event.player.getDamagedHp() <= 1) {
                                        return false;
                                    }
                                }
                                return true;
                            },
                            content() {
                                'step 0';
                                var card = player.getStorage('bjzm征从')[0];
                                player.$throw(card, 1000);
                                game.cardsDiscard(card);
                                player.unmarkAuto('bjzm征从', [card]);
                                game.log(card, '进入了弃牌堆');
                                ('step 1');
                                var str;
                                if (trigger.name == 'recover') {
                                    str = '回复';
                                } else {
                                    str = '';
                                }
                                player.chooseControl(['令此' + str + '数值加一', '令此' + str + '数值减一'], true, function (event, player) {
                                    if (get.attitude(player, trigger.player) > 0) {
                                        if (str == '回复') {
                                            return '令此' + str + '数值加一';
                                        } else {
                                            return '令此' + str + '数值减一';
                                        }
                                    } else {
                                        if (str == '回复') {
                                            return '令此' + str + '数值减一';
                                        } else {
                                            return '令此' + str + '数值加一';
                                        }
                                    }
                                });
                                ('step 2');
                                if (result.index == 0) {
                                    trigger.num++;
                                } else {
                                    trigger.num--;
                                }
                                event.cards = get.cards(2);
                                ('step 3');
                                if (event.cards.length > 1) {
                                    player.chooseCardButton('将<伐城>牌分配给任意角色', true, event.cards, [1, event.cards.length]).set('ai', function (button) {
                                        if (ui.selected.buttons.length == 0) return 1;
                                        return 0;
                                    });
                                } else if (event.cards.length == 1) {
                                    event._result = { links: event.cards.slice(0), bool: true };
                                } else {
                                    event.finish();
                                }
                                ('step 4');
                                if (result.links?.length) {
                                    for (var i = 0; i < result.links.length; i++) {
                                        event.cards.remove(result.links[i]);
                                    }
                                    event.togive = result.links.slice(0);
                                    player
                                        .chooseTarget('将' + get.translation(result.links) + '交给一名角色', true)
                                        .set('ai', function (target) {
                                            var att = get.attitude(_status.event.player, target);
                                            if (_status.event.enemy) {
                                                return -att;
                                            } else if (att > 0) {
                                                return att / (1 + target.countCards('h'));
                                            } else {
                                                return att / 100;
                                            }
                                        })
                                        .set('enemy', get.value(event.togive[0], player, 'raw') < 0);
                                }
                                ('step 5');
                                if (result.targets?.length) {
                                    result.targets[0].gain(event.togive, 'draw');
                                    player.line(result.targets[0], 'green');
                                    game.log(result.targets[0], '获得了' + get.cnNumber(event.togive.length) + '张牌');
                                    event.goto(3);
                                }
                            },
                        },

