                        bjzm协歹: {
                            trigger: { global: 'phaseJieshuBegin' },
                            filter(event, player) {
                                var sourceDamage = event.player.getHistory('sourceDamage');
                                return event.player != player && sourceDamage.length;
                            },
                            content() {
                                'step 0';
                                player
                                    .chooseControl(['选项一', '选项二', 'cancel2'], function (event, player) {
                                        if (get.attitude(player, trigger.player) > 0) {
                                            if (player.hasSha()) return '选项一';
                                            return '选项二';
                                        } else if (get.attitude(player, trigger.player) < 0) {
                                            if (player.hasSha()) return '选项二';
                                            return '选项一';
                                        } else return 'cancel2';
                                    })
                                    .set('prompt', get.prompt2('bjzm协歹'))
                                    .set('choiceList', ['1.你可以令这些角色随机使用一张武器牌.', '2.你可以令该角色随机使用一张武器牌.']);
                                ('step 1');
                                event.targets = [];
                                if (result.index == 0) {
                                    var sourceDamage = trigger.player.getHistory('sourceDamage');
                                    var card;
                                    for (const i of sourceDamage) {
                                        // card = get.cardPile(function (card) {
                                        //     return get.type(card) == 'equip' && get.subtype(card) == 'equip1';
                                        // });
                                        card = get.randomCards(1, function (card) {
                                            return get.type(card) == 'equip' && get.subtype(card) == 'equip1';
                                        });
                                        if (card) {
                                            i.player.gain(card, 'gain2');
                                            //i.player.equip(card);
                                            i.player.useCard(card, player);
                                        }
                                        event.targets.push(i.player);
                                    }
                                } else if (result.index == 1) {
                                    var card = get.cardPile(function (card) {
                                        return get.type(card) == 'equip' && get.subtype(card) == 'equip1';
                                    });
                                    if (card) {
                                        trigger.player.$gain(card, 'gain2');
                                        trigger.player.equip(card);
                                    }
                                    event.targets.push(trigger.player);
                                } else {
                                    event.finish();
                                }
                                ('step 2');
                                player
                                    .chooseCard(1, '你可以使用一张【杀】或普通锦囊牌.且此牌目标改为这些角色.', 'h', function (card) {
                                        if (
                                            !game.hasPlayer(function (current) {
                                                return player.canUse(card, current);
                                            })
                                        ) {
                                            return false;
                                        }
                                        //if (card.suit=='club'||card.name == 'jiedao') return false;
                                        return card.name == 'sha' || get.type(card) == 'trick';
                                    })
                                    .set('ai', function (card) {
                                        if (get.attitude(player, event.targets[0]) < 0 && player.hasSha()) {
                                            return card.name == 'sha';
                                        } else {
                                            return player.getUseValue(card);
                                        }
                                    });
                                ('step 3');
                                if (result.cards?.length) {
                                    event.card = result.cards[0];
                                    if (event.card.suit == 'club' || event.card.name == 'jiedao') {
                                        player.discard(event.card);
                                        player
                                            .chooseTarget(1, true, function (card, player, target) {
                                                return !event.targets.includes(target);
                                            })
                                            .set('ai', function (target) {
                                                return 1 - get.attitude(_status.event.player, target);
                                            })
                                            .set('prompt', '选择【借刀杀人】的被杀者');
                                    } else {
                                        player.useCard(event.card, event.targets);
                                        event.finish();
                                    }
                                }
                                ('step 4');
                                if (result.targets?.length) {
                                    event.target1 = result.targets[0];
                                } else event.finish();
                                ('step 5');
                                event.target = event.targets.shift();
                                event.target.useCard({ name: 'sha' }, event.target1).set('addCount', false);
                                var cards = event.target.getCards('e', { subtype: 'equip1' });
                                if (cards.length) player.gain(cards, event.target, 'give');
                                ('step 6');
                                if (event.targets.length) event.goto(5);
                            },
                            forced: true,
                        },
