                        bjzm界天成: {
                            trigger: {
                                player: 'phaseJieshuBegin',
                            },
                            forced: true,
                            preHidden: true,
                            content() {
                                'step 0';
                                var cards = player.getCards('s');
                                game.cardsGotoOrdering(cards);
                                var next = player.chooseToMove();
                                next.set('list', [['牌堆顶'], ['牌堆底', cards]]);
                                next.set('filterMove', function (from, to, moved) {
                                    //from 是要移动的卡牌 ,  to是要移动的位置 值为0时是第一个框       moved是框里牌的数组
                                    if (to == 0) {
                                        var suits = [];
                                        for (const c of moved[0]) {
                                            if (!suits.includes(c.suit)) suits.push(c.suit);
                                        }
                                        if (suits.includes(from.suit)) return false;
                                    }
                                    return true;
                                });
                                next.set('filterOk', function (moved) {
                                    return moved[0].length <= 4;
                                });
                                next.set('prompt', get.prompt2('bjzm界天成'));
                                next.processAI = function (list) {
                                    var cards = list[1][1],
                                        target = _status.event.player.next;
                                    const att = get.attitude(player, target);
                                    const top = [],
                                        bottom = cards;
                                    for (const i of target.getCards('j')) {
                                        const judge = get.judge(i);
                                        bottom.sort((a, b) => (judge(b) - judge(a)) * att); //态度大于0价值高的牌放前面
                                        if (bottom.length) {
                                            top.push(bottom.shift());
                                        }
                                    }
                                    bottom.sort((a, b) => (get.value(b) - get.value(a)) * att); //态度大于0价值高的牌放前面
                                    while (bottom.length) {
                                        top.push(bottom.shift());
                                    }
                                    if (get.attitude(player, player1) > 0) {
                                        return [top, bottom];
                                    } else {
                                        return [bottom, top];
                                    }
                                };
                                ('step 1');
                                var top = result.moved[0];
                                var bottom = result.moved[1];
                                top.reverse();
                                for (var i = 0; i < top.length; i++) {
                                    ui.cardPile.insertBefore(top[i], ui.cardPile.firstChild);
                                }
                                for (var i = 0; i < bottom.length; i++) {
                                    ui.cardPile.appendChild(bottom[i]);
                                }
                                player.popup(get.cnNumber(top.length) + '上' + get.cnNumber(bottom.length) + '下');
                                game.log(player, '将' + get.cnNumber(top.length) + '张牌置于牌堆顶');
                                game.log(player, '将' + get.cnNumber(bottom.length) + '张牌置于牌堆底');
                                game.updateRoundNumber();
                                player.unmarkSkill('bjzm界追形');
                                ('step 2');
                                //因为强制会出现手牌显示不整齐
                                var hs = player.getCards('h');
                                //刷新手牌的显示解决显示不整齐问题
                                player.directgains(hs, null);
                            },
                            ai: {
                                threaten: 1.2,
                            },
                        },
