                            check(event, player) {
                                return event.name != 'phaseUse';
                            },
                            content() {
                                'step 0';
                                //['phaseZhunbei','phaseDraw','phaseUse','phaseDiscard','phaseJieshu']
                                player.chooseToDiscard('he', function (card) {
                                    var customHistory = player.getHistory('custom', function (evt) {
                                        return evt.bjzm逐影suits;
                                    });
                                    if (customHistory.length && customHistory[0].bjzm逐影suits.includes(card.suit)) {
                                        return false;
                                    }
                                    return true;
                                });
                                ('step 1');
                                if (result.bool) {
                                    var customHistory = player.getHistory('custom', function (evt) {
                                        return evt.bjzm逐影suits;
                                    });
                                    if (!customHistory.length) {
                                        player.getHistory('custom').push({ bjzm逐影suits: [result.cards[0].suit] });
                                    } else {
                                        customHistory[0].bjzm逐影suits.push(result.cards[0].suit);
                                    }
                                    player.chooseUseTarget('视为使用一张没有距离限制的【杀】', { name: 'sha' }, false, 'nodistance');
                                } else event.finish();
                                ('step 2');
                                if (
                                    player.getHistory('sourceDamage', function (evt) {
                                        return evt.getParent(4) == event;
                                    }).length
                                ) {
                                    player.storage.bjzm逐影额外执行一次此阶段 = trigger.name;
                                    if (!player.storage.bjzm逐影限制) {
                                        player.storage.bjzm逐影限制 = [trigger.name];
                                    } else {
                                        player.storage.bjzm逐影限制.push(trigger.name);
                                    }
                                } else {
                                    var evt = event.getParent(trigger.name);
                                    if (evt && evt.name) {
                                        evt.skipped = true;
                                    }
                                    player.skip(trigger.name);
                                }
                            },
                            group: ['bjzm逐影额外执行一次此阶段1', 'bjzm逐影额外执行一次此阶段2', 'bjzm逐影额外执行一次此阶段3', 'bjzm逐影额外执行一次此阶段4', 'bjzm逐影额外执行一次此阶段5'],
