                        bjzm纵却: {
                            trigger: { player: 'useCardToTarget' },
                            filter(event, player) {
                                var evt = player.getHistory('useCard', function (evt) {
                                    return evt.card.name == 'sha';
                                });
                                if (evt.length > 1) return false;
                                return event.card.name == 'sha' && game.players.length >= 3;
                            },
                            content() {
                                'step 0';
                                event.players = game.filterPlayer(function (current) {
                                    return trigger.target.inRange(current) && current != player;
                                });
                                event.choiceList = ['令魏无忌的【杀】不可被响应', '令魏无忌的【杀】伤害+1.', '令魏无忌的【杀】不计入次数'];
                                ('step 1');
                                event.target1 = event.players.shift();
                                if (event.target1) {
                                    event.target1.chooseCard('he', '是否选择一张牌交给' + get.translation(player)).set('ai', function (card) {
                                        if (get.attitude(event.target1, player) > 0 && event.choiceList.length) return 8 - get.value(card);
                                        return 0;
                                    });
                                } else event.finish();
                                ('step 2');
                                if (result.bool && event.choiceList.length) {
                                    player.gain(result.cards, event.target1, 'giveAuto');
                                    event.target1
                                        .chooseControl('cancel2')
                                        .set('prompt', get.prompt2('bjzm纵却'))
                                        .set('choiceList', event.choiceList)
                                        .set('ai', function () {
                                            //event.target1为第一个被选中的目标
                                            if (get.attitude(event.target1, trigger.target) < 0) return 0;
                                            return 'cancel2';
                                        });
                                }
                                ('step 3');
                                if (result.control != 'cancel2') {
                                    /**
                                     * trigger:{player:'useCardToTarget'},的时机 时用
                                     * 伤害加1
                                     */
                                    function addDamage() {
                                        //只能用在usecard世时机
                                        //if(!trigger.baseDamage) trigger.baseDamage=2;
                                        var map = trigger.customArgs;
                                        var id = trigger.target.playerid;
                                        if (!map[id]) {
                                            map[id] = {};
                                        }
                                        if (!map[id].extraDamage) {
                                            map[id].extraDamage = 0;
                                        }
                                        map[id].extraDamage++;
                                        event.choiceList.remove(event.choiceList[1]);
                                    }
                                    if (event.choiceList.length == 3) {
                                        if (result.control == '选项一') {
                                            trigger.parent.directHit.push(trigger.target);
                                            event.choiceList.remove(event.choiceList[0]);
                                        } else if (result.control == '选项二') {
                                            addDamage();
                                        } else {
                                            //杀的次数加一
                                            if (player.stat[player.stat.length - 1].card.sha > 0) {
                                                player.stat[player.stat.length - 1].card.sha--;
                                            }
                                            event.choiceList.remove(event.choiceList[2]);
                                        }
                                    } else if (event.choiceList.length == 2) {
                                        if (result.control == '选项一') {
                                            if (event.choiceList[0] == '令魏无忌的【杀】不可被响应') {
                                                trigger.parent.directHit.push(trigger.target);
                                            } else if (event.choiceList[0] == '令魏无忌的【杀】伤害+1.') {
                                                addDamage();
                                            }
                                            event.choiceList.remove(event.choiceList[0]);
                                        } else {
                                            if (event.choiceList[1] == '令魏无忌的【杀】不计入次数') {
                                                //杀的次数加一
                                                if (player.stat[player.stat.length - 1].card.sha > 0) {
                                                    player.stat[player.stat.length - 1].card.sha--;
                                                }
                                            } else if (event.choiceList[1] == '令魏无忌的【杀】伤害+1.') {
                                                addDamage();
                                            }
                                            event.choiceList.remove(event.choiceList[1]);
                                        }
                                    } else {
                                        if (result.control == '选项一') {
                                            if (event.choiceList[0] == '令魏无忌的【杀】不可被响应') {
                                                trigger.parent.directHit.push(trigger.target);
                                            } else if (event.choiceList[0] == '令魏无忌的【杀】伤害+1.') {
                                                addDamage();
                                            } else {
                                                //杀的次数加一
                                                if (player.stat[player.stat.length - 1].card.sha > 0) {
                                                    player.stat[player.stat.length - 1].card.sha--;
                                                }
                                            }
                                            event.choiceList.remove(event.choiceList[0]);
                                        }
                                    }
                                }
                                ('step 4');
                                if (event.players.length && event.players[0].isIn()) event.goto(1);
                            },
                        },

