                        bjzm难鲁die: {
                            trigger: {
                                player: 'dieBefore',
                            },
                            forced: true,
                            content() {
                                'step 0';
                                //弃掉所有人手中的南蛮和万箭齐发
                                game.countPlayer(function (current) {
                                    if (current.countCards('h', { name: 'nanman' || 'wanjian' })) {
                                        player.line(current);
                                        current.discard(current.getCards('h', { name: 'nanman' || 'wanjian' }));
                                    }
                                });
                                ('step 1');
                                var discardPile = ui.discardPile;
                                var cardPile = ui.cardPile;
                                //从游戏中移除南蛮入侵和万箭齐发
                                function deleteTheCardGlobally(pile, cardNameArray) {
                                    //pile为牌堆容器
                                    //nodeList转成数组
                                    var cardPile = Array.from(pile.childNodes);
                                    if (!cardPile && !cardPile.length) return;
                                    //过滤卡牌
                                    var reCardPile = cardPile.filter(function (card) {
                                        //return card.name !== "nanman" && card.name !== "wanjian";
                                        return !cardNameArray.includes(card.name);
                                    });
                                    if (!reCardPile.length) return;
                                    //删除cardPile所有子节点
                                    for (var i = pile.childNodes.length - 1; i >= 0; i--) {
                                        pile.removeChild(pile.childNodes[i]);
                                    }
                                    //给ui.cardPile添加一个子元素
                                    pile.appendChild(reCardPile[0]);
                                    if (reCardPile.length > 1) {
                                        //再添加的子元素(reCardPile[0])后面添加其他元素
                                        for (var j = 1; j < reCardPile.length; j++) {
                                            pile.insertBefore(reCardPile[j], reCardPile[0]);
                                        }
                                    }
                                }
                                //全局移除谋牌
                                deleteTheCardGlobally(discardPile, ['nanman', 'wanjian']);
                                deleteTheCardGlobally(cardPile, ['nanman', 'wanjian']);
                            },
                        },

