                                        var map = {};
                                        for (var i = 0; i < cards.length; i++) {
                                            var type = get.type(cards[i], 'trick');
                                            map[type == 'basic' ? cards[i].name : type] = true;
                                        }
                                        if (map.equip) return 'equip';
                                        if (map.trick) return 'trick';
                                        if (map.sha) return 'sha';
                                        if (map.tao) return 'tao';
                                        return 0;
