                                if (event.player === player) return false;
                                var targetDamage = [];
                                var targetBool = game.hasPlayer2(function (current) {
                                    var arrayDamage = current.getHistory('damage');
                                    for (var i = 0; i < arrayDamage.length; i++) {
                                        //伤害来源有触发的玩家
                                        if (arrayDamage[i].source === event.player) {
                                            //将受到伤害的玩家保存到targetDamage数组
                                            targetDamage.push(arrayDamage[i].player);
                                        }
                                    }
                                    return targetDamage.length;
                                });
                                //将结束触发玩家存入数组
                                targetDamage.push(event.player);
                                //储存伤害玩家的数组
                                player.storage.targetDamage = targetDamage;
                                //储存伤害的玩家的数量
                                player.storage.targetDamageLen = targetDamage.length;
                                //return event.player.hp >= player.hp;
                                return targetBool;
